function MyInput({ placeholder, ref }) {
  return (
    <input placeholder={placeholder}
      ref={ref} />
  );
}

function MyForm() {
  const inputRef = useRef(null);
  return (
    <>
      <MyInput ref={inputRef} />
      <button onClick={() =>
        inputRef.current.focus()}>
        Focus
      </button>
    </>
  );
}
